create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,nickname text not null unique check(nickname~'^[a-z0-9._]{3,20}$'),career_xp integer not null default 0,total_score bigint not null default 0,total_runs integer not null default 0,must_change_password boolean not null default false,is_admin boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.seasons(id uuid primary key default gen_random_uuid(),key text not null unique,name text not null,starts_at timestamptz not null,ends_at timestamptz not null,created_at timestamptz not null default now());
create table if not exists public.runs(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,client_run_id text not null,game_id text not null check(game_id in('getir-rush','depo-tetris')),score integer not null check(score>=0),xp integer not null check(xp between 0 and 400),duration_seconds integer not null check(duration_seconds between 0 and 3600),metrics jsonb not null default '{}',completed_at timestamptz not null,created_at timestamptz not null default now(),unique(user_id,client_run_id));
create table if not exists public.xp_ledger(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,amount integer not null check(amount>0),source text not null,source_key text not null,created_at timestamptz not null default now(),unique(user_id,source_key));
create table if not exists public.task_progress(user_id uuid not null references public.profiles(id) on delete cascade,period_key text not null,task_id text not null,value integer not null default 0,rewarded boolean not null default false,updated_at timestamptz not null default now(),primary key(user_id,period_key,task_id));
create table if not exists public.login_rate_limits(id bigint generated always as identity primary key,nickname text not null,ip_hash text not null,success boolean not null,created_at timestamptz not null default now());
create index if not exists runs_user_game_score_idx on public.runs(user_id,game_id,score desc);create index if not exists runs_created_idx on public.runs(created_at desc);create index if not exists rate_limit_lookup_idx on public.login_rate_limits(nickname,ip_hash,created_at desc);
alter table public.profiles enable row level security;alter table public.runs enable row level security;alter table public.xp_ledger enable row level security;alter table public.task_progress enable row level security;alter table public.login_rate_limits enable row level security;
create policy "profile owner reads" on public.profiles for select to authenticated using(id=auth.uid());create policy "profile owner updates" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "run owner reads" on public.runs for select to authenticated using(user_id=auth.uid());create policy "xp owner reads" on public.xp_ledger for select to authenticated using(user_id=auth.uid());create policy "task owner reads" on public.task_progress for select to authenticated using(user_id=auth.uid());
create or replace view public.season_leaderboard with(security_invoker=false) as select p.id user_id,p.nickname,coalesce(sum(x.amount),0)::bigint xp from public.profiles p left join public.xp_ledger x on x.user_id=p.id and x.created_at>=date_trunc('month',now() at time zone 'Europe/Istanbul') group by p.id,p.nickname order by xp desc;
create or replace view public.rush_leaderboard with(security_invoker=false) as select p.id user_id,p.nickname,max(r.score)::bigint score from public.profiles p join public.runs r on r.user_id=p.id and r.game_id='getir-rush' group by p.id,p.nickname order by score desc;
create or replace view public.depo_leaderboard with(security_invoker=false) as select p.id user_id,p.nickname,max(r.score)::bigint score from public.profiles p join public.runs r on r.user_id=p.id and r.game_id='depo-tetris' group by p.id,p.nickname order by score desc;
grant select on public.season_leaderboard,public.rush_leaderboard,public.depo_leaderboard to anon,authenticated;
revoke all on public.login_rate_limits from anon,authenticated;
